package main

import "testing"

// The juniper_mx10004 chassis model gained the one logical unit its CLI
// configures, xe-0/0/0.0, at ifIndex 73. gNMI served a unit 0 under every port
// with its parent's name and ifIndex, while IF-MIB served no unit at all. This
// change added the unit's ifTable and ifXTable rows and raised ifNumber from 72
// to 73. Those rows were machine-generated by diffing the generated chassis
// part at the parent revision against this change and are committed verbatim.
// ipRouteIfIndex of both routes moved to 73, because show route sends both via
// xe-0/0/0.0; they had named xe-0/0/0 and xe-0/0/1. Every added OID name is
// already served by another profile, and no value changed its tag, so the name
// view moves nothing.

// mx10004UnitParentRevision is main at branch time; the digests below were
// taken there and are NOT re-derived from the new tree.
const mx10004UnitParentRevision = "23669469"

const (
	shippedTagDigestBeforeMx10004Unit         = "65b1718472612a75e85ccb5c4a109ddb24ba5f511fa326b8625286709e5654dd"
	shippedOIDEncodingDigestBeforeMx10004Unit = "1e16764e84ee6f73e8ec78f03683bc6c1121bbedd4732f7a2166b75cce09c248"
)

var mx10004UnitEdits = []profileRowEdit{
	{op: editChg, oid: ".1.3.6.1.2.1.2.1.0", before: "72", after: "73"},
	{op: editChg, oid: ".1.3.6.1.2.1.4.21.1.2.0.0.0.0", before: "1", after: "73"},
	{op: editChg, oid: ".1.3.6.1.2.1.4.21.1.2.192.168.1.0", before: "2", after: "73"},
	{op: editAdd, oid: ".1.3.6.1.2.1.2.2.1.1.73", after: "73"},
	{op: editAdd, oid: ".1.3.6.1.2.1.2.2.1.2.73", after: "xe-0/0/0.0"},
	{op: editAdd, oid: ".1.3.6.1.2.1.2.2.1.3.73", after: "53"},
	{op: editAdd, oid: ".1.3.6.1.2.1.2.2.1.4.73", after: "1500"},
	{op: editAdd, oid: ".1.3.6.1.2.1.2.2.1.5.73", after: "4294967295"},
	{op: editAdd, oid: ".1.3.6.1.2.1.2.2.1.6.73", after: "00:1A:2B:3C:00:01"},
	{op: editAdd, oid: ".1.3.6.1.2.1.2.2.1.7.73", after: "1"},
	{op: editAdd, oid: ".1.3.6.1.2.1.2.2.1.8.73", after: "1"},
	{op: editAdd, oid: ".1.3.6.1.2.1.31.1.1.1.1.73", after: "xe-0/0/0.0"},
	{op: editAdd, oid: ".1.3.6.1.2.1.31.1.1.1.6.73", after: "13897247566"},
	{op: editAdd, oid: ".1.3.6.1.2.1.31.1.1.1.10.73", after: "13796012999"},
	{op: editAdd, oid: ".1.3.6.1.2.1.31.1.1.1.15.73", after: "10000"},
	{op: editAdd, oid: ".1.3.6.1.2.1.31.1.1.1.18.73", after: ""},
}

var mx10004UnitAddedOIDNames = []string{}

var mx10004UnitRemovedOIDNames = []string{}

func restoreMx10004Unit(t *testing.T, cur map[[2]string]string) {
	t.Helper()
	reverseProfileEdits(t, cur, juniperMx10004Profile, "juniper_mx10004 logical unit", mx10004UnitEdits)
}

func mx10004UnitOIDNamesBefore(t *testing.T, names []string) []string {
	t.Helper()
	return reverseOIDNameEdits(t, names, "juniper_mx10004 logical unit", mx10004UnitAddedOIDNames, mx10004UnitRemovedOIDNames)
}

func TestMx10004UnitReproducesTheParentCorpus(t *testing.T) {
	if got := corpusTagDigestAt(t, corpusValuesAt(t, mx10004UnitParentRevision), mx10004UnitParentRevision); got != shippedTagDigestBeforeMx10004Unit {
		t.Errorf("reversing the logical unit change gives digest %s, want %s: another shipped row changed without being recorded",
			got, shippedTagDigestBeforeMx10004Unit)
	}
}

func TestMx10004UnitRePinIsOnlyTheEdit(t *testing.T) {
	restored := restoreCorpusOIDNamesTo(t, collectShippedOIDs(t), mx10004UnitParentRevision)
	if got := corpusOIDNameDigest(restored); got != shippedOIDEncodingDigestBeforeMx10004Unit {
		t.Errorf("reversing the logical unit OID names gives digest %s, want %s", got, shippedOIDEncodingDigestBeforeMx10004Unit)
	}
}
